:root {
  /* Colors */
  --color-linen-canvas: #f5f4f1;
  --color-paper: #ffffff;
  --color-graphite-ink: #333333;
  --color-pewter-caption: #8b8c96;
  --color-lapis-signal: #5c6ae4;
  --color-lapis-hairline: #5c6ae433;
  --color-amethyst-cursor: #7366fe;
  --color-slate-dusk: #6c77b0;
  --color-lilac-mist: #817da6;
  --color-steel-haze: #6873a5;
  --color-plum-ember: #8f4d75;
  --color-orchid-glow: #7b4096;
  --color-grape-ink: #55269c;

  /* Typography — Font Families */
  --font-gt-walsheim: "GT Walsheim", "Outfit", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-gt-america-standard: "GT America Standard", "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  /* Typography — Scale */
  --text-small: 14px;
  --leading-small: 1.43;
  --tracking-small: 0px;
  --text-caption: 14px;
  --leading-caption: 1.43;
  --tracking-caption: 0px;
  --text-body: 16px;
  --leading-body: 1.5;
  --tracking-body: 0px;
  --text-body-lg: 18px;
  --leading-body-lg: 1.33;
  --tracking-body-lg: 0px;
  --text-subheading: 24px;
  --leading-subheading: 1.25;
  --tracking-subheading: 0px;
  --text-heading-lg: 56px;
  --leading-heading-lg: 1;
  --tracking-heading-lg: 0px;
  --text-display: 64px;
  --leading-display: 1;
  --tracking-display: 0px;

  /* Typography — Weights */
  --font-weight-light: 300;
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-8: 8px;
  --spacing-10: 10px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-48: 48px;
  --spacing-80: 80px;
  --spacing-96: 96px;
  --spacing-120: 120px;
  --spacing-128: 128px;
  --spacing-192: 192px;

  /* Layout */
  --page-max-width: 1280px;
  --section-gap: 128px;
  --card-padding: 48px;
  --element-gap: 16px;

  /* Border Radius */
  --radius-sm: 8px;
  --radius-md: 16px;
  --radius-lg: 24px;
  --radius-xl: 32px;

  /* Named Radii */
  --radius-cards: 24px;
  --radius-sections: 32px;
  --radius-avatars: 32px;
  --radius-images: 0px 0px 32px;
  --radius-inner-tiles: 16px;
  --radius-buttons: 8px;
  --radius-small-elements: 0px 0px 8px 8px;
  --radius-tags: 8px 8px 8px 0px;

  /* Shadows */
  --shadow-md: rgba(0, 0, 0, 0.1) 11px 11px 40px 0px;
  --shadow-xl: rgba(0, 0, 0, 0.2) 0px 1px 128px 0px;

  /* Surfaces */
  --surface-linen-canvas: #f5f4f1;
  --surface-paper: #ffffff;
  --surface-slate-dusk: #6c77b0;
  --surface-grape-ink: #55269c;
}

